// components/Categories.js
import { useEffect, useState } from "react";

export default function Categories({ onSelectCategory }) {
    const [categories, setCategories] = useState([]);
    const [error, setError] = useState("");

    useEffect(() => {
        const fetchCategories = async () => {
            try {
                const res = await fetch("http://localhost:5000/api/categories"); // повний URL
                const data = await res.json();

                if (!res.ok) {
                    setError(data.message || "Помилка при завантаженні категорій");
                    setCategories([]);
                } else {
                    setCategories(data);
                    setError("");
                }
            } catch (err) {
                console.error("Помилка при запиті до сервера:", err);
                setError("Помилка при запиті до сервера");
                setCategories([]);
            }
        };

        fetchCategories();
    }, []);

    return (
        <div className="space-y-2">
            <h2 className="text-xl font-bold mb-2">Категорії</h2>

            {error && (
                <div className="mb-4 p-3 bg-red-50 border-l-4 border-red-500 rounded-lg">
                    <p className="text-red-700 text-sm font-medium">{error}</p>
                </div>
            )}

            {categories.map(cat => (
                <div
                    key={cat.id}
                    onClick={() => onSelectCategory(cat.id)}
                    className="p-3 bg-white rounded-lg shadow cursor-pointer hover:bg-blue-50 transition"
                >
                    <p className="font-semibold">{cat.name}</p>
                    <p className="text-gray-500 text-sm">{cat.description}</p>
                </div>
            ))}
        </div>
    );
}
